using KBS.BLL.Interfaces; using KBS.DAL.Data; using KBS.Models.DTOs.Inventory; using Microsoft.EntityFrameworkCore;
namespace KBS.BLL.Services;
public class InventoryService(KbsDbContext db) : IInventoryService { public async Task<InventoryResponseDto?> GetByProductIdAsync(long productId,CancellationToken ct=default){var inventory=await db.Inventories.AsNoTracking().FirstOrDefaultAsync(x=>x.ProductId==productId,ct);return inventory is null?null:ToDto(inventory);} public async Task<InventoryResponseDto?> UpdateAsync(long productId,UpdateInventoryDto dto,CancellationToken ct=default){var i=await db.Inventories.SingleOrDefaultAsync(x=>x.ProductId==productId,ct);if(i is null)return null;i.StockQuantity=dto.StockQuantity;i.UpdatedAt=DateTimeOffset.UtcNow;await db.SaveChangesAsync(ct);return ToDto(i);} private static InventoryResponseDto ToDto(KBS.Models.Entities.Inventory x)=>new(){Id=x.Id,ProductId=x.ProductId,StockQuantity=x.StockQuantity,UpdatedAt=x.UpdatedAt}; }
